'use strict';

const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

let idx = 0;
const N = data[idx++];
const K = data[idx++];
const U = data[idx++];

const cards = new Array(N);
for (let i = 0; i < N; i++) {
  cards[i] = data.slice(idx, idx + K);
  idx += K;
}

const position = new Int32Array(U + 1);
for (let i = 0; i < U; i++) {
  position[data[idx++]] = i + 1;
}

let earliest = Infinity;
const winners = [];

for (let i = 0; i < N; i++) {
  let completedAt = 0;
  for (const number of cards[i]) {
    if (position[number] > completedAt) completedAt = position[number];
  }

  if (completedAt < earliest) {
    earliest = completedAt;
    winners.length = 0;
    winners.push(i + 1);
  } else if (completedAt === earliest) {
    winners.push(i + 1);
  }
}

console.log(winners.join(' '));
